#!/usr/bin/env python3
"""Synthetic OpenWrt sysupgrade TAR tests; generated bytes are NOT flashable."""
import importlib.util
import io
import struct
import tarfile
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location(
    "prebuilt_swap_probe", ROOT / "scripts/probe-prebuilt-kernel-swap.py")
probe = importlib.util.module_from_spec(spec)
assert spec.loader
spec.loader.exec_module(probe)


def make_payload(*, fit_size: int = 2048, bad_magic: bool = False) -> tuple[bytes, bytes]:
    fit = bytearray(fit_size)
    fit[:4] = b"BAD!" if bad_magic else probe.FIT_MAGIC
    struct.pack_into(">I", fit, 4, fit_size)
    sqfs = bytearray(4096)
    sqfs[:4] = probe.SQUASHFS_MAGIC
    struct.pack_into("<HH", sqfs, 28, 4, 0)
    struct.pack_into("<Q", sqfs, 40, len(sqfs))
    return bytes(fit), bytes(sqfs)


def fake_firmware(filename: Path, *, fit_size: int = 2048,
                  bad_magic: bool = False,
                  omit_root: bool = False,
                  duplicate_kernel: bool = False) -> None:
    fit, sqfs = make_payload(fit_size=fit_size, bad_magic=bad_magic)
    with tarfile.open(filename, mode="w") as archive:
        for label, payload in (("kernel", fit), ("root", sqfs)):
            if label == "root" and omit_root:
                continue
            info = tarfile.TarInfo("sysupgrade-jdcloud_re-ss-01/" + label)
            info.size = len(payload)
            archive.addfile(info, io.BytesIO(payload))
        if duplicate_kernel:
            info = tarfile.TarInfo("sysupgrade-jdcloud_re-ss-01/kernel")
            info.size = len(fit)
            archive.addfile(info, io.BytesIO(fit))
    # Real sysupgrade files append a fwtool metadata trailer after the tar.
    with filename.open("ab") as file:
        file.write(b"fake-fwtool-metadata")


with tempfile.TemporaryDirectory() as rootdir:
    root = Path(rootdir)
    official = root / "official.bin"
    julius = root / "julius.bin"
    fake_firmware(official)
    fake_firmware(julius, fit_size=4096)
    extracted = root / "extracted"
    a = probe.inspect_sysupgrade(official, extracted=extracted, name="immortalwrt")
    b = probe.inspect_sysupgrade(julius, extracted=extracted, name="julius")
    result = probe.compare(a, b)
    assert result["same_layout"]
    assert result["julius_kernel_fits_target_partition"]
    assert not result["same_kernel_binary"]
    assert not result["kernel_abi_verified"]
    assert not result["publishable"]
    assert a["kernel_member"].endswith("/kernel")
    assert a["rootfs_member"].endswith("/root")
    assert a["rootfs_bytes"] == 4096
    assert (extracted / "julius.fit").read_bytes()[:4] == probe.FIT_MAGIC

    def rejected(filename: Path, expected: str) -> None:
        try:
            probe.inspect_sysupgrade(filename)
        except ValueError as e:
            assert expected in str(e), str(e)
        else:
            raise AssertionError("Accepted malformed sysupgrade: " + expected)

    bad = root / "bad.bin"
    bad.write_bytes(b"not-an-openwrt-tar")
    rejected(bad, "invalid sysupgrade TAR")
    fake_firmware(bad, bad_magic=True)
    rejected(bad, "not an ARM64 FIT")
    fake_firmware(bad, omit_root=True)
    rejected(bad, "expected unique sysupgrade")
    fake_firmware(bad, duplicate_kernel=True)
    rejected(bad, "expected unique sysupgrade")
    assert not probe.safe_tar_member_name("../kernel")
    assert not probe.safe_tar_member_name("/root/kernel")

print("PASS RE-SS-01 sysupgrade TAR/FIT/SquashFS and safe member selection")
